package s08_data_jpa.jpa06_flyway_with_jpa;

/**
 * Klient sklepu — SZKIELET do ćwiczenia 2 lekcji Jpa06FlywayWithJpa (opis: na końcu klasy lekcji).
 * Tabela {@code customers} JUŻ ISTNIEJE (migracja V1__create_tables.sql, dane w V3) — tym razem to encja
 * ma dopasować się do tabeli, a nie odwrotnie. Na razie to zwykła klasa, więc Hibernate jej nie zna
 * i validate jej nie sprawdza.
 *
 * <p>Kolumny tabeli: {@code id bigint generated by default as identity}, {@code full_name varchar(100) not null},
 * {@code city varchar(50)}, {@code email varchar(255) unique}, {@code vip boolean not null}.</p>
 *
 * <p>Uwaga: z ddl-auto=validate każdy błąd w mapowaniu (zła nazwa kolumny, typ) zatrzyma start kontekstu WSZYSTKICH
 * testów tej lekcji — przeczytaj wtedy komunikat „Schema validation: …”, on mówi dokładnie, co poprawić.</p>
 */
// TODO ĆWICZENIE 2: adnotacje encji i tabeli
public class Customer {

    // TODO ĆWICZENIE 2: klucz główny — numer nadaje baza (kolumna identity)
    private Long id;

    // TODO ĆWICZENIE 2: pole nazywa się name, a kolumna full_name
    private String name;

    private String city;

    private String email;

    private boolean vip;

    protected Customer() {
    }

    public Customer(String name, String city, String email, boolean vip) {
        this.name = name;
        this.city = city;
        this.email = email;
        this.vip = vip;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getCity() {
        return city;
    }

    public String getEmail() {
        return email;
    }

    public boolean isVip() {
        return vip;
    }
}
